/**
 * Handing generated fill-sheet files to the browser. Shared by the print sheet and the collector
 * binders page (2026-10-26), so a free placeholder print and a paid one save the same way.
 */
import { zipSync } from 'fflate';

import type { FillSheetPdf } from '@/data/placeholderPdf';

/** Trigger a browser download for generated bytes (PDF by default; ZIP for bundled fill sheets). */
export function saveBytes(bytes: Uint8Array, filename: string, mime = 'application/pdf') {
  const blob = new Blob([bytes as BlobPart], { type: mime });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 10000);
}

/** Filesystem-safe stem from a binder title (kept in sync with the snapshot filename rules). */
export const fileStem = (title: string) => title.replace(/[^\w\- ]+/g, '').trim() || 'binder';

/**
 * Deliver the generated fill-sheet files. Placeholders and art print as SEPARATE PDFs (plain paper
 * vs matte cardstock), and the instructions are a third PDF so the print files carry sheets only
 * and go to a printer or a print service untouched. A single file downloads directly; multiple
 * files go out as ONE ZIP rather than several programmatic downloads — the old staggered approach
 * was unreliable (Chrome prompts for the second download, Safari silently drops it), so a user
 * could get the placeholders and never the art. `suffix` marks archived versions.
 */
export async function saveFillSheetFiles(files: FillSheetPdf[], stem: string, suffix = '') {
  const label = (f: FillSheetPdf) =>
    f.section === 'art' ? 'Art (matte cardstock)'
      : f.section === 'placeholders' ? 'Placeholders (plain paper)'
        : 'Read me first (instructions)';
  const nameFor = (f: FillSheetPdf) => `${stem} - ${label(f)}${suffix}.pdf`;
  if (files.length === 1) {
    saveBytes(files[0].bytes, nameFor(files[0]));
    return;
  }
  const entries: Record<string, Uint8Array> = {};
  for (const f of files) entries[nameFor(f)] = f.bytes;
  // level 0 (store): PDFs are already compressed, so this is a fast container, not a re-compress.
  saveBytes(zipSync(entries, { level: 0 }), `${stem}${suffix}.zip`, 'application/zip');
}
